	private static void assertBoundedWork(NativeWork work, int predicates, int deltas, int pages) {
		assertAll(
				() -> assertThat(work.metadataReads)
						.as("directory discovery and exact dirty counts are bounded by predicates: %s", work)
						.isLessThanOrEqualTo(ADMISSION_ROWS + 2L * predicates + 6),
				() -> assertThat(work.deltaReads)
						.as("delta work follows the small overlay after admission: %s", work)
						.isLessThanOrEqualTo(ADMISSION_ROWS + predicates + 2L * deltas + 4),
				() -> assertThat(work.opens).as("predicate heads share the existing cursor pair: %s", work)
						.isLessThanOrEqualTo(3),
				() -> assertThat(work.pageDecodes).as("warm pages transfer into stream heads: %s", work)
						.isLessThanOrEqualTo(pages + 1L),
				() -> assertThat(work.pageReads).as("page work remains bounded by the physical pages: %s", work)
						.isLessThanOrEqualTo(10L * pages + 32));
		assertThat(work.live).as("exhaustion releases the shared cursors").isEmpty();
	}

	private static void replaceThirtyTwoObjects(Fixture fixture) throws Exception {
		List<Q> original = new ArrayList<>(fixture.quads);
		fixture.store.startTransaction();
		for (int replacement = 0; replacement < 32; replacement++) {
			// Spread the overlay across all eight predicates so shared delta cursor restoration is exercised.
			Q old = original.get(replacement * original.size() / 32 + replacement % 8);
			fixture.remove(old);
			fixture.add(new Q(old.s(), old.p(), old.o() + 1_000_000, old.c()));
		}
		fixture.store.commit();
	}

	private static List<Q> sparseRows(boolean unsigned) {
		List<Q> seed = new ArrayList<>();
		for (int ordinal = 0; ordinal < LmdbPersistentAdjacency.PAGE_QUADS + 65; ordinal++) {
			if (ordinal % 37 != 0) {
				seed.add(sparseQuad(ordinal, 0, unsigned));
				seed.add(sparseQuad(ordinal, 1, unsigned));
			}
		}
		return seed;
	}

	private static Q sparseQuad(int ordinal, int predicate, boolean unsigned) {
		return unsigned ? unsignedQuad(ordinal, predicate == 0 ? 20 : Long.MIN_VALUE + 20)
				: quad(ordinal, 20 + predicate);
	}

	private static void applySparseOverlay(Fixture fixture, boolean unsigned) throws Exception {
		fixture.store.startTransaction();
		for (int predicate = 0; predicate < 2; predicate++) {
			for (int ordinal = 200; ordinal < 216; ordinal++) {
				fixture.remove(sparseQuad(ordinal, predicate, unsigned));
			}
			for (int ordinal = 1050; ordinal < 1082; ordinal++) {
				if (ordinal % 37 != 0) {
					Q old = sparseQuad(ordinal, predicate, unsigned);
					fixture.remove(old);
					fixture.add(new Q(old.s(), old.p(), old.o(), old.c() == 7 ? 0 : 7));
				}
			}
		}
		fixture.store.commit();
	}
